CREATE OR REPLACE FUNCTION public.store_refusal(p_world uuid, p_uid uuid, d deed, p_what text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when d.founded_by is null or p_uid = d.founded_by then null
    when exists (select 1 from deed_member m
                  where m.world_id = p_world and m.founder = d.founded_by and m.uid = p_uid)
      then rank_lacks(p_world, d.founded_by, p_uid, 'use_stores')
    else upper(left(p_what, 1)) || substr(p_what, 2) || ': settlement store of ' || d.name
      || '. Opens for its founder and ranks with Use the settlement stores only.' end
$function$
